		for (int j = 0; j < n; j++) {
			cin >> b[i][j];
		}
	}
	two_sat ts(n);
	for (int j = 0; j < n; j++) {
		for (int i = 0; i < 3; i++) {
			int nxt = (i + 1) % 3;
			ts.add_clause(abs(b[i][j]) - 1, b[i][j] > 0, abs(b[nxt][j]) - 1, b[nxt][j] > 0);
		}
	}
	cout << (ts.satisfiable() ? "YES\n" : "NO\n");
}

